import{_ as a,o as s,c as t,aj as e}from"./chunks/framework.C6uXqnaX.js";const k=JSON.parse('{"title":"Optimizing images","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tutorials/learn-angular/11-optimizing-images.md","filePath":"tutorials/learn-angular/11-optimizing-images.md"}'),n={name:"tutorials/learn-angular/11-optimizing-images.md"};function l(p,i,h,o,r,d){return s(),t("div",null,i[0]||(i[0]=[e(`<h1 id="optimizing-images" tabindex="-1">Optimizing images <a class="header-anchor" href="#optimizing-images" aria-label="Permalink to &quot;Optimizing images&quot;">​</a></h1><p>Images are a big part of many applications, and can be a major contributor to application performance problems, including low <a href="https://web.dev/explore/learn-core-web-vitals" target="_blank" rel="noreferrer">Core Web Vitals</a> scores.</p><p>Image optimization can be a complex topic, but Angular handles most of it for you, with the <code>NgOptimizedImage</code> directive.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Learn more about <a href="/guide/image-optimization">image optimization with NgOptimizedImage in the in-depth guide</a>.</p></div><p>In this activity, you&#39;ll learn how to use <code>NgOptimizedImage</code> to ensure your images are loaded efficiently.</p><hr><h3 id="_1-import-the-ngoptimizedimage-directive" tabindex="-1">1. Import the NgOptimizedImage directive <a class="header-anchor" href="#_1-import-the-ngoptimizedimage-directive" aria-label="Permalink to &quot;1. Import the NgOptimizedImage directive&quot;">​</a></h3><p>In order to leverage the <code>NgOptimizedImage</code> directive, first import it from the <code>@angular/common</code> library and add it to the component <code>imports</code> array.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { NgOptimizedImage } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@angular/common&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  imports: [NgOptimizedImage],</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><h3 id="_2-update-the-src-attribute-to-be-ngsrc" tabindex="-1">2. Update the src attribute to be ngSrc <a class="header-anchor" href="#_2-update-the-src-attribute-to-be-ngsrc" aria-label="Permalink to &quot;2. Update the src attribute to be ngSrc&quot;">​</a></h3><p>To enable the <code>NgOptimizedImage</code> directive, swap out the <code>src</code> attribute for <code>ngSrc</code>. This applies for both static image sources (i.e., <code>src</code>) and dynamic image sources (i.e., <code>[src]</code>).</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { NgOptimizedImage } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@angular/common&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`     ...</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;li&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      Static Image:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &lt;img ngSrc=&quot;/logo.svg&quot; alt=&quot;Angular logo&quot; width=&quot;32&quot; height=&quot;32&quot; /&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;/li&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;li&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      Dynamic Image:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &lt;img [ngSrc]=&quot;logoUrl&quot; [alt]=&quot;logoAlt&quot; width=&quot;32&quot; height=&quot;32&quot; /&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;/li&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ...</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  \`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">imports: [NgOptimizedImage],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><h3 id="_3-add-width-and-height-attributes" tabindex="-1">3. Add width and height attributes <a class="header-anchor" href="#_3-add-width-and-height-attributes" aria-label="Permalink to &quot;3. Add width and height attributes&quot;">​</a></h3><p>Note that in the above code example, each image has both <code>width</code> and <code>height</code> attributes. In order to prevent <a href="https://web.dev/articles/cls" target="_blank" rel="noreferrer">layout shift</a>, the <code>NgOptimizedImage</code> directive requires both size attributes on each image.</p><p>In situations where you can&#39;t or don&#39;t want to specify a static <code>height</code> and <code>width</code> for images, you can use <a href="/guide/image-optimization#using-fill-mode">the <code>fill</code> attribute</a> to tell the image to act like a &quot;background image&quot;, filling its containing element:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">// Container div has &#39;position: &quot;relative&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image-container&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ngSrc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;www.example.com/image.png&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>For the <code>fill</code> image to render properly, its parent element must be styled with <code>position: &quot;relative&quot;</code>, <code>position: &quot;fixed&quot;</code>, or <code>position: &quot;absolute&quot;</code>.</p></div><h3 id="_4-prioritize-important-images" tabindex="-1">4. Prioritize important images <a class="header-anchor" href="#_4-prioritize-important-images" aria-label="Permalink to &quot;4. Prioritize important images&quot;">​</a></h3><p>One of the most important optimizations for loading performance is to prioritize any image which might be the <a href="https://web.dev/articles/optimize-lcp" target="_blank" rel="noreferrer">&quot;LCP element&quot;</a>, which is the largest on-screen graphical element when the page loads. To optimize your loading times, make sure to add the <code>priority</code> attribute to your &quot;hero image&quot; or any other images that you think could be an LCP element.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">img ngSrc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;www.example.com/image.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> height</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;600&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;800&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> priority </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/&gt;</span></span></code></pre></div><h3 id="_5-optional-use-an-image-loader" tabindex="-1">5. Optional: Use an image loader <a class="header-anchor" href="#_5-optional-use-an-image-loader" aria-label="Permalink to &quot;5. Optional: Use an image loader&quot;">​</a></h3><p><code>NgOptimizedImage</code> allows you to specify an <a href="/guide/image-optimization#configuring-an-image-loader-for-ngoptimizedimage">image loader</a>, which tells the directive how to format URLs for your images. Using a loader allows you to define your images with short, relative URLs:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provideImgixLoader</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://my.base.url/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)],</span></span></code></pre></div><p>Final URL will be &#39;<a href="https://my.base.url/image.png" target="_blank" rel="noreferrer">https://my.base.url/image.png</a>&#39;</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ngSrc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image.png&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;600&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;800&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Image loaders are for more than just convenience--they allow you to use the full capabilities of <code>NgOptimizedImage</code>. Learn more about these optimizations and the built-in loaders for popular CDNs <a href="/guide/image-optimization#configuring-an-image-loader-for-ngoptimizedimage">here</a>.</p><p>By adding this directive to your workflow, your images are now loading using best practices with the help of Angular 🎉</p><p>If you would like to learn more, check out the <a href="/guide/image-optimization">documentation for <code>NgOptimizedImage</code></a>. Keep up the great work and let&#39;s learn about routing next.</p>`,28)]))}const c=a(n,[["render",l]]);export{k as __pageData,c as default};
